'use strict';
window.mapModule=(()=>{
 let geometry,profiles,data,actions,metric='votes',city='all',zone='all';
 const $=s=>document.querySelector(s), n=v=>Number(v).toLocaleString('pt-BR'), pct=(v,total)=>total?`${(100*v/total).toFixed(1).replace('.',',')}%`:'0,0%', e=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&quot;'}[c]));
 const colors=['#e5edf2','#cfe4e6','#a4d7d5','#69c1c2','#318eae','#22628e','#173f72','#0e2d53'];
 const capitalNames={325:'Pirituba',403:'Jaraguá',327:'Nossa Senhora do Ó',250:'Lapa'};
 const areaLabel=x=>x.code==='71072'&&capitalNames[x.zone]?`${x.name} · zona ${x.zone} (${capitalNames[x.zone]})`:`${x.name} · zona ${x.zone}`;
 const thresholds={votes:[0,1,3,10,30,100,300],per10k:[0,0.5,1,2,5,10,25]};
 const cityData=new Map(),zoneData=new Map();
 function value(v,profile){return metric==='votes'?v:profile?.registered?10000*v/profile.registered:0}
 function band(v){if(!v)return 0;let i=1;for(const t of thresholds[metric].slice(1)){if(v>t)i++}return Math.min(i,7)}
 function color(v){return colors[band(v)]}
 function legend(){const t=thresholds[metric];$('#mapLegend').innerHTML='<span>Escala:</span>'+colors.map((c,i)=>`<span><i style="background:${c}"></i>${i===0?'0':i===1?`até ${t[1]}`:i<7?`>${t[i-1]}`:`>${t[6]}`}</span>`).join('');}
 function renderMap(){const map=$('#geoShapes');for(const path of map.children){const code=path.dataset.code,entry=cityData.get(code),profile=profiles.municipalities[code];path.setAttribute('fill',color(value(entry.votes,profile)));path.classList.toggle('selected',city===code)}
  $('#mapDetail').textContent=metric==='votes'?'Cor por votos nominais, em classes para mostrar municípios de diferentes tamanhos. Clique no município para abrir suas zonas.':'Votos nominais da candidatura por 10 mil pessoas inscritas no município em julho de 2026. É uma razão de escala, não percentual de votos válidos ou perfil de quem votou.';legend()}
 function renderGrid(){const rows=data.zones.filter(x=>city==='all'||x.code===city).sort((a,b)=>b.votes-a.votes||a.zone-b.zone),head=city==='all'?'Estado de São Paulo':cityData.get(city)?.name||'Município';$('#zoneGridTitle').textContent=`Zonas · ${head}`;$('#zoneGridCount').textContent=`${n(rows.length)} registros por município/zona`;
  const max=rows[0]?.votes||1;$('#zoneHeatGrid').innerHTML=rows.map(x=>{let alpha=Math.max(.08,Math.log1p(x.votes)/Math.log1p(max));let bg=x.votes?`rgba(36,108,177,${(.15+alpha*.77).toFixed(2)})`:'#e7eef3',light=alpha>.6;return `<button class="zoneCell ${zone===String(x.zone)&&city===x.code?'selected':''}" data-code="${e(x.code)}" data-zone="${x.zone}" title="${e(areaLabel(x))}: ${n(x.votes)} votos" style="background:${bg};color:${light?'#fff':'#193c60'}"><b>${x.zone}</b>${n(x.votes)}</button>`}).join('');$('#zoneHeatGrid').onclick=ev=>{const target=ev.target.closest('button[data-zone]');if(target)actions.chooseZone(target.dataset.code,target.dataset.zone)}}
 function profileArea(){if(city!=='all'&&zone!=='all')return profiles.zones[`${city}:${zone}`];if(city!=='all')return profiles.municipalities[city];const p={registered:0,age:{},education:{}};for(const item of Object.values(profiles.municipalities)){p.registered+=item.registered;for(const [k,v] of Object.entries(item.age))p.age[k]=(p.age[k]||0)+v;for(const [k,v] of Object.entries(item.education))p.education[k]=(p.education[k]||0)+v}return p}
 function renderContext(){const p=profileArea();if(!p){$('#areaContext').innerHTML='<p class="mapDataError">Não há perfil do eleitorado para esta área.</p>';return}
  const area=city==='all'?'Estado de São Paulo':`${cityData.get(city)?.name||''}${zone==='all'?'':` · zona ${zone}`}`,voters=city==='all'?data.candidate.votes:zone==='all'?cityData.get(city)?.votes:zoneData.get(`${city}:${zone}`)?.votes||0,rate=p.registered?(10000*voters/p.registered).toFixed(1).replace('.',','):'—';let top=data.zones.filter(x=>city==='all'||x.code===city).sort((a,b)=>b.votes-a.votes).slice(0,5);
  const ageOrder=['16–24','25–44','45–59','60+'];const age=ageOrder.map(k=>`<div class="contextBar"><span>${k}</span><div class="contextTrack"><i style="width:${100*(p.age[k]||0)/p.registered}%"></i></div><b>${pct(p.age[k]||0,p.registered)}</b></div>`).join('');const complete=(p.education['SUPERIOR COMPLETO']||0)+(p.education['ENSINO MÉDIO COMPLETO']||0);
  $('#areaContext').innerHTML=`<div class="contextLead"><b>${e(area)}</b><br>Cadastro do eleitorado · 14/07/2026</div><div class="contextStats"><div class="contextStat"><small>Inscritos na área</small><b>${n(p.registered)}</b></div><div class="contextStat"><small>Votos / 10 mil inscritos</small><b>${rate}</b></div></div><div class="contextBars"><b>Faixas etárias dos inscritos</b>${age}</div><div class="contextStat"><small>Ensino médio ou superior completo no cadastro</small><b>${pct(complete,p.registered)}</b></div><div class="strengthList"><h4>Maiores contagens de votos na seleção</h4>${top.map(x=>`<div><span>${e(areaLabel(x))}</span><b>${n(x.votes)}</b></div>`).join('')}</div>`}
 function render(nextCity,nextZone){city=nextCity;zone=nextZone;if(!geometry||!profiles)return;renderMap();renderGrid();renderContext()}
 async function init(d,callbacks){data=d;actions=callbacks;for(const x of d.cities)cityData.set(x.code,x);for(const x of d.zones)zoneData.set(`${x.code}:${x.zone}`,x);
  try{const [geoRes,profileRes]=await Promise.all([fetch('map.json'),fetch('profiles.json')]);if(!geoRes.ok||!profileRes.ok)throw Error('arquivos indisponíveis');[geometry,profiles]=await Promise.all([geoRes.json(),profileRes.json()]);if(geometry.municipalities.length!==645||Object.keys(profiles.municipalities).length!==645)throw Error('cobertura municipal incompleta');
   const g=$('#geoShapes');for(const x of geometry.municipalities){const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d',x.path);path.dataset.code=x.code;path.setAttribute('tabindex','0');path.setAttribute('aria-label',`${x.name}: ${n(cityData.get(x.code)?.votes||0)} votos`);path.addEventListener('click',()=>actions.chooseCity(x.code));path.addEventListener('keydown',ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();actions.chooseCity(x.code)}});path.addEventListener('mouseenter',()=>{const p=profiles.municipalities[x.code],v=cityData.get(x.code)?.votes||0;$('#geoTooltip').textContent=`${x.name} · ${n(v)} votos · ${p?.registered?n(p.registered)+' inscritos':'cadastro indisponível'}`;$('#geoTooltip').classList.remove('hidden')});path.addEventListener('mouseleave',()=>$('#geoTooltip').classList.add('hidden'));g.append(path)}
   for(const b of document.querySelectorAll('[data-mapmetric]'))b.onclick=()=>{metric=b.dataset.mapmetric;document.querySelectorAll('[data-mapmetric]').forEach(x=>x.classList.toggle('active',x===b));renderMap()};render(city,zone);
  }catch(error){$('#mapDetail').textContent=`Não foi possível carregar a cartografia ou o perfil agregado: ${error.message}`;$('#areaContext').textContent='O cadastro agregado não está disponível nesta visualização.'}}
 return {init,render};
})();
